import clusterdata.datatypes.TaskEvent;
import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/**
 * Reads a single gzipped CSV file of task events, sorted by ascending
 * timestamp, and emits each row with its event-time watermark.
 */
public class GzipTaskEventSource implements SourceFunction<TaskEvent> {

    private final String path;
    private volatile boolean running = true;

    public GzipTaskEventSource(String path) {
        this.path = path;
    }

    @Override
    public void run(SourceContext<TaskEvent> ctx) throws Exception {
        try (BufferedReader r = new BufferedReader(
                new InputStreamReader(new GZIPInputStream(new FileInputStream(path)),
                        StandardCharsets.UTF_8))) {
            String line;
            while (running && (line = r.readLine()) != null) {
                if (line.isEmpty()) continue;
                TaskEvent e;
                try {
                    e = TaskEvent.fromCsv(line);
                } catch (Exception ex) {
                    continue;
                }
                if (e.jobId < 0) continue;
                // The input file is already sorted by timestamp (microseconds).
                // Convert to milliseconds for Flink event-time processing.
                long tsMs = e.timestamp / 1000L;
                ctx.collectWithTimestamp(e, tsMs);
            }
            ctx.emitWatermark(new org.apache.flink.streaming.api.watermark.Watermark(Long.MAX_VALUE));
        }
    }

    @Override
    public void cancel() {
        running = false;
    }
}
