import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import clusterdata.utils.GzipJobEventSource;
import clusterdata.utils.GzipTaskEventSource;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.AggregateFunction;
import org.apache.flink.api.common.functions.ReduceFunction;
import org.apache.flink.api.java.functions.KeySelector;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        final int sesssize = params.getInt("sesssize", 600);

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        SourceFunction<TaskEvent> taskSource = taskSourceOrTest(new GzipTaskEventSource(taskInput));
        // Read job events too so the pipeline consumes them, even if they don't
        // affect the aggregation. The AppBase test hooks require the source to
        // exist when substituted.
        if (jobInput != null) {
            env.addSource(jobSourceOrTest(new GzipJobEventSource(jobInput)))
                    .name("job-events")
                    .filter(e -> false); // consume but discard
        }

        DataStream<TaskEvent> tasks = env.addSource(taskSource)
                .name("task-events")
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((e, ts) -> e.timestamp / 1000L));

        DataStream<Tuple2<Long, Integer>> longestPerJob = tasks
                .filter(e -> e.eventType == TaskEvent.SUBMIT)
                .keyBy((KeySelector<TaskEvent, Long>) e -> e.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .aggregate(new CountAgg(), new EmitJobCount())
                .keyBy((KeySelector<Tuple2<Long, Integer>, Long>) t -> t.f0)
                .reduce((ReduceFunction<Tuple2<Long, Integer>>) (a, b) ->
                        a.f1 >= b.f1 ? a : b);

        if (out != null) {
            longestPerJob.addSink(out).name("test-sink");
        } else {
            longestPerJob.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE)
                    .setParallelism(1)
                    .name("file-sink");
        }

        env.execute("LongestSessionPerJob");
    }

    /** Counts SUBMIT events within one session window. */
    public static class CountAgg implements AggregateFunction<TaskEvent, Integer, Integer> {
        @Override public Integer createAccumulator() { return 0; }
        @Override public Integer add(TaskEvent value, Integer acc) { return acc + 1; }
        @Override public Integer getResult(Integer acc) { return acc; }
        @Override public Integer merge(Integer a, Integer b) { return a + b; }
    }

    /** Combines the window's aggregated count with its key (jobId). */
    public static class EmitJobCount
            implements org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction<
                    Integer, Tuple2<Long, Integer>, Long,
                    org.apache.flink.streaming.api.windowing.windows.TimeWindow> {
        @Override
        public void process(Long jobId, Context ctx, Iterable<Integer> elements,
                            org.apache.flink.util.Collector<Tuple2<Long, Integer>> out) {
            int count = elements.iterator().next();
            out.collect(Tuple2.of(jobId, count));
        }
    }
}
